package main

// A small go.mod reader that follows the syntax and validation rules of the
// go.mod format closely enough to extract the module path and report
// syntax/semantic errors in the conventional "file:line: message" form.

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type modPosition struct {
	Line     int
	LineRune int
	Byte     int
}

type modError struct {
	Filename string
	Pos      modPosition
	Verb     string
	ModPath  string
	Err      error
}

func (e *modError) Error() string {
	var pos string
	if e.Pos.LineRune > 1 {
		pos = fmt.Sprintf("%s:%d:%d: ", e.Filename, e.Pos.Line, e.Pos.LineRune)
	} else if e.Pos.Line > 0 {
		pos = fmt.Sprintf("%s:%d: ", e.Filename, e.Pos.Line)
	} else if e.Filename != "" {
		pos = fmt.Sprintf("%s: ", e.Filename)
	}
	var directive string
	if e.ModPath != "" {
		directive = fmt.Sprintf("%s %s: ", e.Verb, e.ModPath)
	} else if e.Verb != "" {
		directive = fmt.Sprintf("%s: ", e.Verb)
	}
	return pos + directive + e.Err.Error()
}

type modErrorList []modError

func (l modErrorList) Error() string {
	parts := make([]string, 0, len(l))
	for i := range l {
		parts = append(parts, l[i].Error())
	}
	return strings.Join(parts, "\n")
}

type modTokenKind int

const (
	modTokEOF modTokenKind = -(iota + 1)
	modTokEOLComment
	modTokIdent
	modTokString
	modTokComment
)

func (k modTokenKind) isEOL() bool {
	return k == modTokEOF || k == modTokEOLComment || k == '\n'
}

type modToken struct {
	kind   modTokenKind
	pos    modPosition
	endPos modPosition
	text   string
}

type modLine struct {
	Start   modPosition
	Token   []string
	InBlock bool
}

type modStmt struct {
	line  *modLine   // single line statement
	block *modBlock  // block statement
}

type modBlock struct {
	Start modPosition
	Token []string
	Line  []*modLine
}

type modInput struct {
	filename  string
	complete  []byte
	remaining []byte
	pos       modPosition
	token     modToken
	errs      modErrorList
	stmts     []modStmt
}

type modPanic struct{}

func (in *modInput) fail(s string) {
	in.errs = append(in.errs, modError{Filename: in.filename, Pos: in.pos, Err: errors.New(s)})
	panic(modPanic{})
}

func (in *modInput) eof() bool { return len(in.remaining) == 0 }

func (in *modInput) peekRune() int {
	if len(in.remaining) == 0 {
		return 0
	}
	r, _ := utf8.DecodeRune(in.remaining)
	return int(r)
}

func (in *modInput) peekPrefix(prefix string) bool {
	return strings.HasPrefix(string(in.remaining), prefix)
}

func (in *modInput) readRune() int {
	if len(in.remaining) == 0 {
		in.fail("internal lexer error: readRune at EOF")
	}
	r, size := utf8.DecodeRune(in.remaining)
	in.remaining = in.remaining[size:]
	if r == '\n' {
		in.pos.Line++
		in.pos.LineRune = 1
	} else {
		in.pos.LineRune++
	}
	in.pos.Byte += size
	return int(r)
}

func (in *modInput) startToken() {
	in.token = modToken{pos: in.pos}
}

func (in *modInput) endToken(kind modTokenKind) {
	in.token.kind = kind
	in.token.text = string(in.complete[in.token.pos.Byte:in.pos.Byte])
	in.token.endPos = in.pos
}

func (in *modInput) peek() modTokenKind { return in.token.kind }

func (in *modInput) lex() modToken {
	tok := in.token
	in.readToken()
	return tok
}

func modIsIdent(c int) bool {
	switch r := rune(c); r {
	case ' ', '(', ')', '[', ']', '{', '}', ',':
		return false
	default:
		return !unicode.IsSpace(r) && unicode.IsPrint(r)
	}
}

func (in *modInput) readToken() {
	for !in.eof() {
		c := in.peekRune()
		if c == ' ' || c == '\t' || c == '\r' {
			in.readRune()
			continue
		}
		if in.peekPrefix("//") {
			in.startToken()
			i := strings.LastIndex(string(in.complete[:in.pos.Byte]), "\n")
			suffix := len(strings.TrimSpace(string(in.complete[i+1:in.pos.Byte]))) > 0
			in.readRune()
			in.readRune()
			for len(in.remaining) > 0 && in.readRune() != '\n' {
			}
			if !suffix {
				in.endToken(modTokComment)
				return
			}
			in.endToken(modTokEOLComment)
			return
		}
		if in.peekPrefix("/*") {
			in.fail("mod files must use // comments (not /* */ comments)")
		}
		break
	}

	in.startToken()
	if in.eof() {
		in.endToken(modTokEOF)
		return
	}

	switch c := in.peekRune(); c {
	case '\n', '(', ')', '[', ']', '{', '}', ',':
		in.readRune()
		in.endToken(modTokenKind(c))
		return
	case '"', '`':
		quote := c
		in.readRune()
		for {
			if in.eof() {
				in.pos = in.token.pos
				in.fail("unexpected EOF in string")
			}
			if in.peekRune() == '\n' {
				in.fail("unexpected newline in string")
			}
			c := in.readRune()
			if c == quote {
				break
			}
			if c == '\\' && quote != '`' {
				if in.eof() {
					in.pos = in.token.pos
					in.fail("unexpected EOF in string")
				}
				in.readRune()
			}
		}
		in.endToken(modTokString)
		return
	}

	if c := in.peekRune(); !modIsIdent(c) {
		in.fail(fmt.Sprintf("unexpected input character %#q", rune(c)))
	}
	for modIsIdent(in.peekRune()) {
		if in.peekPrefix("//") {
			break
		}
		if in.peekPrefix("/*") {
			in.fail("mod files must use // comments (not /* */ comments)")
		}
		in.readRune()
	}
	in.endToken(modTokIdent)
}

func (in *modInput) parseFile() {
	for {
		switch in.peek() {
		case '\n':
			in.lex()
		case modTokComment:
			in.lex()
		case modTokEOF:
			return
		default:
			in.parseStmt()
		}
	}
}

func (in *modInput) parseStmt() {
	tok := in.lex()
	start := tok.pos
	tokens := []string{tok.text}
	for {
		tok := in.lex()
		switch {
		case tok.kind.isEOL():
			in.stmts = append(in.stmts, modStmt{line: &modLine{Start: start, Token: tokens}})
			return
		case tok.kind == '(':
			if next := in.peek(); next.isEOL() {
				in.stmts = append(in.stmts, modStmt{block: in.parseLineBlock(start, tokens)})
				return
			} else if next == ')' {
				rparen := in.lex()
				if in.peek().isEOL() {
					in.lex()
					in.stmts = append(in.stmts, modStmt{block: &modBlock{Start: start, Token: tokens}})
					return
				}
				tokens = append(tokens, tok.text, rparen.text)
			} else {
				tokens = append(tokens, tok.text)
			}
		default:
			tokens = append(tokens, tok.text)
		}
	}
}

func (in *modInput) parseLineBlock(start modPosition, token []string) *modBlock {
	x := &modBlock{Start: start, Token: token}
	for {
		switch in.peek() {
		case modTokEOLComment:
			in.lex()
		case '\n':
			in.lex()
		case modTokComment:
			in.lex()
		case modTokEOF:
			in.fail(fmt.Sprintf("syntax error (unterminated block started at %s:%d:%d)", in.filename, x.Start.Line, x.Start.LineRune))
		case ')':
			in.lex()
			if !in.peek().isEOL() {
				in.fail("syntax error (expected newline after closing paren)")
			}
			in.lex()
			return x
		default:
			x.Line = append(x.Line, in.parseLine())
		}
	}
}

func (in *modInput) parseLine() *modLine {
	tok := in.lex()
	if tok.kind.isEOL() {
		in.fail("internal parse error: parseLine at end of line")
	}
	start := tok.pos
	tokens := []string{tok.text}
	for {
		tok := in.lex()
		if tok.kind.isEOL() {
			return &modLine{Start: start, Token: tokens, InBlock: true}
		}
		tokens = append(tokens, tok.text)
	}
}

// parseGoMod parses go.mod contents and returns the module path, or "" if the
// file does not declare a module.
func parseGoMod(filename string, data []byte) (modulePath string, hasModule bool, err error) {
	in := &modInput{
		filename:  filename,
		complete:  data,
		remaining: data,
		pos:       modPosition{Line: 1, LineRune: 1, Byte: 0},
	}
	func() {
		defer func() {
			if e := recover(); e != nil {
				if _, ok := e.(modPanic); !ok {
					in.errs = append(in.errs, modError{Filename: in.filename, Pos: in.pos, Err: fmt.Errorf("%v", e)})
				}
			}
		}()
		in.readToken()
		in.parseFile()
	}()
	if len(in.errs) > 0 {
		return "", false, in.errs
	}

	st := &modState{filename: filename}
	for _, s := range in.stmts {
		if s.line != nil {
			st.add(nil, s.line, s.line.Token[0], s.line.Token[1:])
			continue
		}
		b := s.block
		if len(b.Token) > 1 {
			st.errs = append(st.errs, modError{Filename: filename, Pos: b.Start, Err: fmt.Errorf("unknown block type: %s", strings.Join(b.Token, " "))})
			continue
		}
		switch b.Token[0] {
		case "module", "godebug", "require", "exclude", "replace", "retract", "tool":
			for _, l := range b.Line {
				st.add(b, l, b.Token[0], l.Token)
			}
		default:
			st.errs = append(st.errs, modError{Filename: filename, Pos: b.Start, Err: fmt.Errorf("unknown block type: %s", strings.Join(b.Token, " "))})
		}
	}
	if len(st.errs) > 0 {
		return "", false, st.errs
	}
	return st.modulePath, st.hasModule, nil
}

type modState struct {
	filename     string
	errs         modErrorList
	hasModule    bool
	modulePath   string
	hasGo        bool
	hasToolchain bool
}

func (st *modState) add(block *modBlock, line *modLine, verb string, args []string) {
	wrapError := func(err error) {
		st.errs = append(st.errs, modError{Filename: st.filename, Pos: line.Start, Err: err})
	}
	wrapModPathError := func(modPath string, err error) {
		st.errs = append(st.errs, modError{Filename: st.filename, Pos: line.Start, ModPath: modPath, Verb: verb, Err: err})
	}
	errorf := func(format string, a ...interface{}) {
		wrapError(fmt.Errorf(format, a...))
	}

	switch verb {
	default:
		errorf("unknown directive: %s", verb)

	case "go":
		if st.hasGo {
			errorf("repeated go statement")
			return
		}
		if len(args) != 1 {
			errorf("go directive expects exactly one argument")
			return
		} else if !isGoVersion(args[0]) {
			errorf("invalid go version '%s': must match format 1.23.0", args[0])
			return
		}
		st.hasGo = true

	case "toolchain":
		if st.hasToolchain {
			errorf("repeated toolchain statement")
			return
		}
		if len(args) != 1 {
			errorf("toolchain directive expects exactly one argument")
			return
		} else if !isToolchainName(args[0]) {
			errorf("invalid toolchain version '%s': must match format go1.23.0 or default", args[0])
			return
		}
		st.hasToolchain = true

	case "godebug":
		if len(args) != 1 || strings.ContainsAny(args[0], "\"`',") {
			errorf("usage: godebug key=value")
			return
		}
		if _, _, ok := strings.Cut(args[0], "="); !ok {
			errorf("usage: godebug key=value")
			return
		}

	case "module":
		if st.hasModule {
			errorf("repeated module statement")
			return
		}
		st.hasModule = true
		if len(args) != 1 {
			errorf("usage: module module/path")
			return
		}
		s, err := modParseString(&args[0])
		if err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
		st.modulePath = s

	case "require", "exclude":
		if len(args) != 2 {
			errorf("usage: %s module/path v1.2.3", verb)
			return
		}
		s, err := modParseString(&args[0])
		if err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
		v, err := modParseVersion(verb, s, &args[1])
		if err != nil {
			wrapError(err)
			return
		}
		pathMajor, ok := modulePathMajor(s)
		if !ok {
			wrapError(&modError{Verb: verb, ModPath: s, Err: fmt.Errorf("invalid module path")})
			return
		}
		if err := checkPathMajor(v, pathMajor); err != nil {
			wrapModPathError(s, err)
			return
		}

	case "replace":
		if err := st.parseReplace(line, verb, args); err != nil {
			st.errs = append(st.errs, *err)
		}

	case "retract":
		if err := modParseRetract(verb, &args); err != nil {
			wrapError(err)
			return
		}
		if len(args) > 0 {
			errorf("unexpected token after version: %q", args[0])
			return
		}

	case "tool":
		if len(args) != 1 {
			errorf("tool directive expects exactly one argument")
			return
		}
		if _, err := modParseString(&args[0]); err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
	}
}

func (st *modState) parseReplace(line *modLine, verb string, args []string) *modError {
	wrapModPathError := func(modPath string, err error) *modError {
		return &modError{Filename: st.filename, Pos: line.Start, ModPath: modPath, Verb: verb, Err: err}
	}
	wrapError := func(err error) *modError {
		return &modError{Filename: st.filename, Pos: line.Start, Err: err}
	}
	errorf := func(format string, a ...interface{}) *modError {
		return wrapError(fmt.Errorf(format, a...))
	}

	arrow := 2
	if len(args) >= 2 && args[1] == "=>" {
		arrow = 1
	}
	if len(args) < arrow+2 || len(args) > arrow+3 || args[arrow] != "=>" {
		return errorf("usage: %s module/path [v1.2.3] => other/module v1.4\n\t or %s module/path [v1.2.3] => ../local/directory", verb, verb)
	}
	s, err := modParseString(&args[0])
	if err != nil {
		return errorf("invalid quoted string: %v", err)
	}
	pathMajor, ok := modulePathMajor(s)
	if !ok {
		return wrapModPathError(s, fmt.Errorf("invalid module path"))
	}
	if len(args) == arrow+2 || len(args) == arrow+3 {
		if arrow == 2 {
			v, err := modParseVersion(verb, s, &args[1])
			if err != nil {
				return wrapError(err)
			}
			if err := checkPathMajor(v, pathMajor); err != nil {
				return wrapModPathError(s, err)
			}
		}
	}
	ns, err := modParseString(&args[arrow+1])
	if err != nil {
		return errorf("invalid quoted string: %v", err)
	}
	nv := ""
	if len(args) == arrow+2 {
		if !isLocalPath(ns) {
			return errorf("replacement module without version must be directory path (rooted or starting with . or ..)")
		}
		if filepathSlash(ns) != ns {
			return errorf("replacement directory appears to be Windows path (on a non-windows system)")
		}
	}
	if len(args) == arrow+3 {
		nv, err = modParseVersion(verb, ns, &args[arrow+2])
		if err != nil {
			return wrapError(err)
		}
		if isLocalPath(ns) {
			return errorf("replacement module directory path %q cannot have version", ns)
		}
	}
	_ = nv
	return nil
}

func filepathSlash(s string) string { return s }

func isLocalPath(s string) bool {
	return strings.HasPrefix(s, "./") || strings.HasPrefix(s, "../") || strings.HasPrefix(s, "/") ||
		s == "." || s == ".." || strings.HasPrefix(s, ".\\") || strings.HasPrefix(s, "..\\")
}

func modParseString(s *string) (string, error) {
	t := *s
	if strings.HasPrefix(t, `"`) {
		var err error
		if t, err = strconv.Unquote(t); err != nil {
			return "", err
		}
	} else if strings.ContainsAny(t, "\"'`") {
		return "", fmt.Errorf("unquoted string cannot contain quote")
	}
	return t, nil
}

func modParseVersion(verb, path string, s *string) (string, error) {
	t, err := modParseString(s)
	if err != nil {
		return "", &modError{Verb: verb, ModPath: path, Err: fmt.Errorf("version %q invalid: %v", *s, err)}
	}
	if v := canonicalSemver(t); v != "" {
		return v, nil
	}
	return "", &modError{Verb: verb, ModPath: path, Err: fmt.Errorf("version %q invalid: must be of the form v1.2.3", t)}
}

func modParseRetract(verb string, args *[]string) error {
	toks := *args
	if len(toks) == 0 || toks[0] == "(" {
		return fmt.Errorf("expected '[' or version")
	}
	if toks[0] != "[" {
		if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
			return err
		}
		*args = toks[1:]
		return nil
	}
	toks = toks[1:]
	if len(toks) == 0 {
		return fmt.Errorf("expected version after '['")
	}
	if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
		return err
	}
	toks = toks[1:]
	if len(toks) == 0 || toks[0] != "," {
		return fmt.Errorf("expected ',' after version")
	}
	toks = toks[1:]
	if len(toks) == 0 {
		return fmt.Errorf("expected version after ','")
	}
	if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
		return err
	}
	toks = toks[1:]
	if len(toks) == 0 || toks[0] != "]" {
		return fmt.Errorf("expected ']' after version")
	}
	*args = toks[1:]
	return nil
}

func isGoVersion(s string) bool {
	// ([1-9][0-9]*)\.(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?([a-z]+[0-9]+)?
	i := 0
	num := func(allowZeroLead bool) bool {
		start := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == start {
			return false
		}
		if s[start] == '0' && i-start > 1 {
			return false
		}
		if !allowZeroLead && s[start] == '0' {
			return false
		}
		return true
	}
	if !num(false) {
		return false
	}
	if i >= len(s) || s[i] != '.' {
		return false
	}
	i++
	if !num(true) {
		return false
	}
	if i < len(s) && s[i] == '.' {
		i++
		if !num(true) {
			return false
		}
	}
	if i < len(s) {
		start := i
		for i < len(s) && s[i] >= 'a' && s[i] <= 'z' {
			i++
		}
		if i == start {
			return false
		}
		dstart := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == dstart {
			return false
		}
	}
	return i == len(s)
}

func isToolchainName(s string) bool {
	if s == "default" {
		return true
	}
	if !strings.HasPrefix(s, "go") {
		return false
	}
	rest := s[2:]
	if i := strings.Index(rest, "-"); i >= 0 {
		if i == len(rest)-1 {
			return false
		}
		rest = rest[:i]
	}
	return isGoVersion(rest)
}

func modulePathMajor(path string) (string, bool) {
	if strings.HasPrefix(path, "gopkg.in/") {
		i := strings.LastIndex(path, ".")
		if i < 0 {
			return "", false
		}
		suffix := path[i:]
		if len(suffix) >= 3 && suffix[1] == 'v' && isDigits(suffix[2:]) {
			if j := strings.Index(suffix, "-unstable"); j >= 0 {
				return suffix, true
			}
			return suffix, true
		}
		return "", false
	}
	i := len(path)
	for i > 0 && path[i-1] >= '0' && path[i-1] <= '9' {
		i--
	}
	if i <= 1 || i == len(path) || path[i-1] != 'v' || path[i-2] != '/' {
		return "", true
	}
	if path[i] == '0' {
		return "", true
	}
	if path[i:] == "1" {
		return "", true
	}
	return path[i-2:], true
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func checkPathMajor(v, pathMajor string) error {
	if strings.HasPrefix(pathMajor, ".v") && strings.HasSuffix(pathMajor, "-unstable") {
		pathMajor = strings.TrimSuffix(pathMajor, "-unstable")
	}
	if strings.HasPrefix(v, "v0.0.0-") && pathMajor == ".v1" {
		return nil
	}
	m := semverMajor(v)
	if pathMajor == "" {
		if m == "v0" || m == "v1" || strings.HasSuffix(v, "+incompatible") {
			return nil
		}
		pathMajor = "v0 or v1"
	} else if pathMajor[0] == '/' || pathMajor[0] == '.' {
		if m == pathMajor[1:] {
			return nil
		}
		pathMajor = pathMajor[1:]
	}
	return fmt.Errorf("version %q invalid: should be %s, not %s", v, pathMajor, m)
}

// --- minimal semver handling ---

func semverMajor(v string) string {
	if !strings.HasPrefix(v, "v") {
		return ""
	}
	i := 1
	for i < len(v) && v[i] >= '0' && v[i] <= '9' {
		i++
	}
	return v[:i]
}

func canonicalSemver(v string) string {
	p, ok := parseSemver(v)
	if !ok {
		return ""
	}
	if p.build != "" {
		return v[:len(v)-len(p.build)]
	}
	if p.short != "" {
		return v + p.short
	}
	return v
}

type semverParsed struct {
	major, minor, patch, short, prerelease, build string
}

func parseSemver(v string) (p semverParsed, ok bool) {
	if v == "" || v[0] != 'v' {
		return
	}
	var num func(string) (string, string, bool)
	num = func(s string) (string, string, bool) {
		i := 0
		for i < len(s) && '0' <= s[i] && s[i] <= '9' {
			i++
		}
		if i == 0 || (s[0] == '0' && i != 1) {
			return "", "", false
		}
		return s[:i], s[i:], true
	}
	if p.major, v, ok = num(v[1:]); !ok {
		return
	}
	if v == "" {
		p.minor = "0"
		p.patch = "0"
		p.short = ".0.0"
		return p, true
	}
	if v[0] != '.' {
		ok = false
		return
	}
	if p.minor, v, ok = num(v[1:]); !ok {
		return
	}
	if v == "" {
		p.patch = "0"
		p.short = ".0"
		return p, true
	}
	if v[0] != '.' {
		ok = false
		return
	}
	if p.patch, v, ok = num(v[1:]); !ok {
		return
	}
	if len(v) > 0 && v[0] == '-' {
		i := 1
		for i < len(v) && v[i] != '+' {
			i++
		}
		p.prerelease = v[:i]
		if !semverIdentList(p.prerelease[1:], true) {
			ok = false
			return
		}
		v = v[i:]
	}
	if len(v) > 0 && v[0] == '+' {
		p.build = v
		if !semverIdentList(v[1:], false) {
			ok = false
			return
		}
		v = ""
	}
	if v != "" {
		ok = false
		return
	}
	ok = true
	return
}

func semverIdentList(s string, numericCheck bool) bool {
	if s == "" {
		return false
	}
	for _, part := range strings.Split(s, ".") {
		if part == "" {
			return false
		}
		allDigits := true
		for _, c := range part {
			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '-') {
				return false
			}
			if c < '0' || c > '9' {
				allDigits = false
			}
		}
		if numericCheck && allDigits && len(part) > 1 && part[0] == '0' {
			return false
		}
	}
	return true
}
EOF
echo done"}

actions.command:
mkdir -p /workspace && cat > /workspace/modfile.go <<'EOF'
package main

// A small go.mod reader that follows the syntax and validation rules of the
// go.mod format closely enough to extract the module path and report
// syntax/semantic errors in the conventional "file:line: message" form.

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type modPosition struct {
	Line     int
	LineRune int
	Byte     int
}

type modError struct {
	Filename string
	Pos      modPosition
	Verb     string
	ModPath  string
	Err      error
}

func (e *modError) Error() string {
	var pos string
	if e.Pos.LineRune > 1 {
		pos = fmt.Sprintf("%s:%d:%d: ", e.Filename, e.Pos.Line, e.Pos.LineRune)
	} else if e.Pos.Line > 0 {
		pos = fmt.Sprintf("%s:%d: ", e.Filename, e.Pos.Line)
	} else if e.Filename != "" {
		pos = fmt.Sprintf("%s: ", e.Filename)
	}
	var directive string
	if e.ModPath != "" {
		directive = fmt.Sprintf("%s %s: ", e.Verb, e.ModPath)
	} else if e.Verb != "" {
		directive = fmt.Sprintf("%s: ", e.Verb)
	}
	return pos + directive + e.Err.Error()
}

type modErrorList []modError

func (l modErrorList) Error() string {
	parts := make([]string, 0, len(l))
	for i := range l {
		parts = append(parts, l[i].Error())
	}
	return strings.Join(parts, "\n")
}

type modTokenKind int

const (
	modTokEOF modTokenKind = -(iota + 1)
	modTokEOLComment
	modTokIdent
	modTokString
	modTokComment
)

func (k modTokenKind) isEOL() bool {
	return k == modTokEOF || k == modTokEOLComment || k == '\n'
}

type modToken struct {
	kind   modTokenKind
	pos    modPosition
	endPos modPosition
	text   string
}

type modLine struct {
	Start   modPosition
	Token   []string
	InBlock bool
}

type modStmt struct {
	line  *modLine   // single line statement
	block *modBlock  // block statement
}

type modBlock struct {
	Start modPosition
	Token []string
	Line  []*modLine
}

type modInput struct {
	filename  string
	complete  []byte
	remaining []byte
	pos       modPosition
	token     modToken
	errs      modErrorList
	stmts     []modStmt
}

type modPanic struct{}

func (in *modInput) fail(s string) {
	in.errs = append(in.errs, modError{Filename: in.filename, Pos: in.pos, Err: errors.New(s)})
	panic(modPanic{})
}

func (in *modInput) eof() bool { return len(in.remaining) == 0 }

func (in *modInput) peekRune() int {
	if len(in.remaining) == 0 {
		return 0
	}
	r, _ := utf8.DecodeRune(in.remaining)
	return int(r)
}

func (in *modInput) peekPrefix(prefix string) bool {
	return strings.HasPrefix(string(in.remaining), prefix)
}

func (in *modInput) readRune() int {
	if len(in.remaining) == 0 {
		in.fail("internal lexer error: readRune at EOF")
	}
	r, size := utf8.DecodeRune(in.remaining)
	in.remaining = in.remaining[size:]
	if r == '\n' {
		in.pos.Line++
		in.pos.LineRune = 1
	} else {
		in.pos.LineRune++
	}
	in.pos.Byte += size
	return int(r)
}

func (in *modInput) startToken() {
	in.token = modToken{pos: in.pos}
}

func (in *modInput) endToken(kind modTokenKind) {
	in.token.kind = kind
	in.token.text = string(in.complete[in.token.pos.Byte:in.pos.Byte])
	in.token.endPos = in.pos
}

func (in *modInput) peek() modTokenKind { return in.token.kind }

func (in *modInput) lex() modToken {
	tok := in.token
	in.readToken()
	return tok
}

func modIsIdent(c int) bool {
	switch r := rune(c); r {
	case ' ', '(', ')', '[', ']', '{', '}', ',':
		return false
	default:
		return !unicode.IsSpace(r) && unicode.IsPrint(r)
	}
}

func (in *modInput) readToken() {
	for !in.eof() {
		c := in.peekRune()
		if c == ' ' || c == '\t' || c == '\r' {
			in.readRune()
			continue
		}
		if in.peekPrefix("//") {
			in.startToken()
			i := strings.LastIndex(string(in.complete[:in.pos.Byte]), "\n")
			suffix := len(strings.TrimSpace(string(in.complete[i+1:in.pos.Byte]))) > 0
			in.readRune()
			in.readRune()
			for len(in.remaining) > 0 && in.readRune() != '\n' {
			}
			if !suffix {
				in.endToken(modTokComment)
				return
			}
			in.endToken(modTokEOLComment)
			return
		}
		if in.peekPrefix("/*") {
			in.fail("mod files must use // comments (not /* */ comments)")
		}
		break
	}

	in.startToken()
	if in.eof() {
		in.endToken(modTokEOF)
		return
	}

	switch c := in.peekRune(); c {
	case '\n', '(', ')', '[', ']', '{', '}', ',':
		in.readRune()
		in.endToken(modTokenKind(c))
		return
	case '"', '`':
		quote := c
		in.readRune()
		for {
			if in.eof() {
				in.pos = in.token.pos
				in.fail("unexpected EOF in string")
			}
			if in.peekRune() == '\n' {
				in.fail("unexpected newline in string")
			}
			c := in.readRune()
			if c == quote {
				break
			}
			if c == '\\' && quote != '`' {
				if in.eof() {
					in.pos = in.token.pos
					in.fail("unexpected EOF in string")
				}
				in.readRune()
			}
		}
		in.endToken(modTokString)
		return
	}

	if c := in.peekRune(); !modIsIdent(c) {
		in.fail(fmt.Sprintf("unexpected input character %#q", rune(c)))
	}
	for modIsIdent(in.peekRune()) {
		if in.peekPrefix("//") {
			break
		}
		if in.peekPrefix("/*") {
			in.fail("mod files must use // comments (not /* */ comments)")
		}
		in.readRune()
	}
	in.endToken(modTokIdent)
}

func (in *modInput) parseFile() {
	for {
		switch in.peek() {
		case '\n':
			in.lex()
		case modTokComment:
			in.lex()
		case modTokEOF:
			return
		default:
			in.parseStmt()
		}
	}
}

func (in *modInput) parseStmt() {
	tok := in.lex()
	start := tok.pos
	tokens := []string{tok.text}
	for {
		tok := in.lex()
		switch {
		case tok.kind.isEOL():
			in.stmts = append(in.stmts, modStmt{line: &modLine{Start: start, Token: tokens}})
			return
		case tok.kind == '(':
			if next := in.peek(); next.isEOL() {
				in.stmts = append(in.stmts, modStmt{block: in.parseLineBlock(start, tokens)})
				return
			} else if next == ')' {
				rparen := in.lex()
				if in.peek().isEOL() {
					in.lex()
					in.stmts = append(in.stmts, modStmt{block: &modBlock{Start: start, Token: tokens}})
					return
				}
				tokens = append(tokens, tok.text, rparen.text)
			} else {
				tokens = append(tokens, tok.text)
			}
		default:
			tokens = append(tokens, tok.text)
		}
	}
}

func (in *modInput) parseLineBlock(start modPosition, token []string) *modBlock {
	x := &modBlock{Start: start, Token: token}
	for {
		switch in.peek() {
		case modTokEOLComment:
			in.lex()
		case '\n':
			in.lex()
		case modTokComment:
			in.lex()
		case modTokEOF:
			in.fail(fmt.Sprintf("syntax error (unterminated block started at %s:%d:%d)", in.filename, x.Start.Line, x.Start.LineRune))
		case ')':
			in.lex()
			if !in.peek().isEOL() {
				in.fail("syntax error (expected newline after closing paren)")
			}
			in.lex()
			return x
		default:
			x.Line = append(x.Line, in.parseLine())
		}
	}
}

func (in *modInput) parseLine() *modLine {
	tok := in.lex()
	if tok.kind.isEOL() {
		in.fail("internal parse error: parseLine at end of line")
	}
	start := tok.pos
	tokens := []string{tok.text}
	for {
		tok := in.lex()
		if tok.kind.isEOL() {
			return &modLine{Start: start, Token: tokens, InBlock: true}
		}
		tokens = append(tokens, tok.text)
	}
}

// parseGoMod parses go.mod contents and returns the module path, or "" if the
// file does not declare a module.
func parseGoMod(filename string, data []byte) (modulePath string, hasModule bool, err error) {
	in := &modInput{
		filename:  filename,
		complete:  data,
		remaining: data,
		pos:       modPosition{Line: 1, LineRune: 1, Byte: 0},
	}
	func() {
		defer func() {
			if e := recover(); e != nil {
				if _, ok := e.(modPanic); !ok {
					in.errs = append(in.errs, modError{Filename: in.filename, Pos: in.pos, Err: fmt.Errorf("%v", e)})
				}
			}
		}()
		in.readToken()
		in.parseFile()
	}()
	if len(in.errs) > 0 {
		return "", false, in.errs
	}

	st := &modState{filename: filename}
	for _, s := range in.stmts {
		if s.line != nil {
			st.add(nil, s.line, s.line.Token[0], s.line.Token[1:])
			continue
		}
		b := s.block
		if len(b.Token) > 1 {
			st.errs = append(st.errs, modError{Filename: filename, Pos: b.Start, Err: fmt.Errorf("unknown block type: %s", strings.Join(b.Token, " "))})
			continue
		}
		switch b.Token[0] {
		case "module", "godebug", "require", "exclude", "replace", "retract", "tool":
			for _, l := range b.Line {
				st.add(b, l, b.Token[0], l.Token)
			}
		default:
			st.errs = append(st.errs, modError{Filename: filename, Pos: b.Start, Err: fmt.Errorf("unknown block type: %s", strings.Join(b.Token, " "))})
		}
	}
	if len(st.errs) > 0 {
		return "", false, st.errs
	}
	return st.modulePath, st.hasModule, nil
}

type modState struct {
	filename     string
	errs         modErrorList
	hasModule    bool
	modulePath   string
	hasGo        bool
	hasToolchain bool
}

func (st *modState) add(block *modBlock, line *modLine, verb string, args []string) {
	wrapError := func(err error) {
		st.errs = append(st.errs, modError{Filename: st.filename, Pos: line.Start, Err: err})
	}
	wrapModPathError := func(modPath string, err error) {
		st.errs = append(st.errs, modError{Filename: st.filename, Pos: line.Start, ModPath: modPath, Verb: verb, Err: err})
	}
	errorf := func(format string, a ...interface{}) {
		wrapError(fmt.Errorf(format, a...))
	}

	switch verb {
	default:
		errorf("unknown directive: %s", verb)

	case "go":
		if st.hasGo {
			errorf("repeated go statement")
			return
		}
		if len(args) != 1 {
			errorf("go directive expects exactly one argument")
			return
		} else if !isGoVersion(args[0]) {
			errorf("invalid go version '%s': must match format 1.23.0", args[0])
			return
		}
		st.hasGo = true

	case "toolchain":
		if st.hasToolchain {
			errorf("repeated toolchain statement")
			return
		}
		if len(args) != 1 {
			errorf("toolchain directive expects exactly one argument")
			return
		} else if !isToolchainName(args[0]) {
			errorf("invalid toolchain version '%s': must match format go1.23.0 or default", args[0])
			return
		}
		st.hasToolchain = true

	case "godebug":
		if len(args) != 1 || strings.ContainsAny(args[0], "\"`',") {
			errorf("usage: godebug key=value")
			return
		}
		if _, _, ok := strings.Cut(args[0], "="); !ok {
			errorf("usage: godebug key=value")
			return
		}

	case "module":
		if st.hasModule {
			errorf("repeated module statement")
			return
		}
		st.hasModule = true
		if len(args) != 1 {
			errorf("usage: module module/path")
			return
		}
		s, err := modParseString(&args[0])
		if err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
		st.modulePath = s

	case "require", "exclude":
		if len(args) != 2 {
			errorf("usage: %s module/path v1.2.3", verb)
			return
		}
		s, err := modParseString(&args[0])
		if err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
		v, err := modParseVersion(verb, s, &args[1])
		if err != nil {
			wrapError(err)
			return
		}
		pathMajor, ok := modulePathMajor(s)
		if !ok {
			wrapError(&modError{Verb: verb, ModPath: s, Err: fmt.Errorf("invalid module path")})
			return
		}
		if err := checkPathMajor(v, pathMajor); err != nil {
			wrapModPathError(s, err)
			return
		}

	case "replace":
		if err := st.parseReplace(line, verb, args); err != nil {
			st.errs = append(st.errs, *err)
		}

	case "retract":
		if err := modParseRetract(verb, &args); err != nil {
			wrapError(err)
			return
		}
		if len(args) > 0 {
			errorf("unexpected token after version: %q", args[0])
			return
		}

	case "tool":
		if len(args) != 1 {
			errorf("tool directive expects exactly one argument")
			return
		}
		if _, err := modParseString(&args[0]); err != nil {
			errorf("invalid quoted string: %v", err)
			return
		}
	}
}

func (st *modState) parseReplace(line *modLine, verb string, args []string) *modError {
	wrapModPathError := func(modPath string, err error) *modError {
		return &modError{Filename: st.filename, Pos: line.Start, ModPath: modPath, Verb: verb, Err: err}
	}
	wrapError := func(err error) *modError {
		return &modError{Filename: st.filename, Pos: line.Start, Err: err}
	}
	errorf := func(format string, a ...interface{}) *modError {
		return wrapError(fmt.Errorf(format, a...))
	}

	arrow := 2
	if len(args) >= 2 && args[1] == "=>" {
		arrow = 1
	}
	if len(args) < arrow+2 || len(args) > arrow+3 || args[arrow] != "=>" {
		return errorf("usage: %s module/path [v1.2.3] => other/module v1.4\n\t or %s module/path [v1.2.3] => ../local/directory", verb, verb)
	}
	s, err := modParseString(&args[0])
	if err != nil {
		return errorf("invalid quoted string: %v", err)
	}
	pathMajor, ok := modulePathMajor(s)
	if !ok {
		return wrapModPathError(s, fmt.Errorf("invalid module path"))
	}
	if len(args) == arrow+2 || len(args) == arrow+3 {
		if arrow == 2 {
			v, err := modParseVersion(verb, s, &args[1])
			if err != nil {
				return wrapError(err)
			}
			if err := checkPathMajor(v, pathMajor); err != nil {
				return wrapModPathError(s, err)
			}
		}
	}
	ns, err := modParseString(&args[arrow+1])
	if err != nil {
		return errorf("invalid quoted string: %v", err)
	}
	nv := ""
	if len(args) == arrow+2 {
		if !isLocalPath(ns) {
			return errorf("replacement module without version must be directory path (rooted or starting with . or ..)")
		}
		if filepathSlash(ns) != ns {
			return errorf("replacement directory appears to be Windows path (on a non-windows system)")
		}
	}
	if len(args) == arrow+3 {
		nv, err = modParseVersion(verb, ns, &args[arrow+2])
		if err != nil {
			return wrapError(err)
		}
		if isLocalPath(ns) {
			return errorf("replacement module directory path %q cannot have version", ns)
		}
	}
	_ = nv
	return nil
}

func filepathSlash(s string) string { return s }

func isLocalPath(s string) bool {
	return strings.HasPrefix(s, "./") || strings.HasPrefix(s, "../") || strings.HasPrefix(s, "/") ||
		s == "." || s == ".." || strings.HasPrefix(s, ".\\") || strings.HasPrefix(s, "..\\")
}

func modParseString(s *string) (string, error) {
	t := *s
	if strings.HasPrefix(t, `"`) {
		var err error
		if t, err = strconv.Unquote(t); err != nil {
			return "", err
		}
	} else if strings.ContainsAny(t, "\"'`") {
		return "", fmt.Errorf("unquoted string cannot contain quote")
	}
	return t, nil
}

func modParseVersion(verb, path string, s *string) (string, error) {
	t, err := modParseString(s)
	if err != nil {
		return "", &modError{Verb: verb, ModPath: path, Err: fmt.Errorf("version %q invalid: %v", *s, err)}
	}
	if v := canonicalSemver(t); v != "" {
		return v, nil
	}
	return "", &modError{Verb: verb, ModPath: path, Err: fmt.Errorf("version %q invalid: must be of the form v1.2.3", t)}
}

func modParseRetract(verb string, args *[]string) error {
	toks := *args
	if len(toks) == 0 || toks[0] == "(" {
		return fmt.Errorf("expected '[' or version")
	}
	if toks[0] != "[" {
		if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
			return err
		}
		*args = toks[1:]
		return nil
	}
	toks = toks[1:]
	if len(toks) == 0 {
		return fmt.Errorf("expected version after '['")
	}
	if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
		return err
	}
	toks = toks[1:]
	if len(toks) == 0 || toks[0] != "," {
		return fmt.Errorf("expected ',' after version")
	}
	toks = toks[1:]
	if len(toks) == 0 {
		return fmt.Errorf("expected version after ','")
	}
	if _, err := modParseVersion(verb, "", &toks[0]); err != nil {
		return err
	}
	toks = toks[1:]
	if len(toks) == 0 || toks[0] != "]" {
		return fmt.Errorf("expected ']' after version")
	}
	*args = toks[1:]
	return nil
}

func isGoVersion(s string) bool {
	// ([1-9][0-9]*)\.(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?([a-z]+[0-9]+)?
	i := 0
	num := func(allowZeroLead bool) bool {
		start := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == start {
			return false
		}
		if s[start] == '0' && i-start > 1 {
			return false
		}
		if !allowZeroLead && s[start] == '0' {
			return false
		}
		return true
	}
	if !num(false) {
		return false
	}
	if i >= len(s) || s[i] != '.' {
		return false
	}
	i++
	if !num(true) {
		return false
	}
	if i < len(s) && s[i] == '.' {
		i++
		if !num(true) {
			return false
		}
	}
	if i < len(s) {
		start := i
		for i < len(s) && s[i] >= 'a' && s[i] <= 'z' {
			i++
		}
		if i == start {
			return false
		}
		dstart := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == dstart {
			return false
		}
	}
	return i == len(s)
}

func isToolchainName(s string) bool {
	if s == "default" {
		return true
	}
	if !strings.HasPrefix(s, "go") {
		return false
	}
	rest := s[2:]
	if i := strings.Index(rest, "-"); i >= 0 {
		if i == len(rest)-1 {
			return false
		}
		rest = rest[:i]
	}
	return isGoVersion(rest)
}

func modulePathMajor(path string) (string, bool) {
	if strings.HasPrefix(path, "gopkg.in/") {
		i := strings.LastIndex(path, ".")
		if i < 0 {
			return "", false
		}
		suffix := path[i:]
		if len(suffix) >= 3 && suffix[1] == 'v' && isDigits(suffix[2:]) {
			if j := strings.Index(suffix, "-unstable"); j >= 0 {
				return suffix, true
			}
			return suffix, true
		}
		return "", false
	}
	i := len(path)
	for i > 0 && path[i-1] >= '0' && path[i-1] <= '9' {
		i--
	}
	if i <= 1 || i == len(path) || path[i-1] != 'v' || path[i-2] != '/' {
		return "", true
	}
	if path[i] == '0' {
		return "", true
	}
	if path[i:] == "1" {
		return "", true
	}
	return path[i-2:], true
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func checkPathMajor(v, pathMajor string) error {
	if strings.HasPrefix(pathMajor, ".v") && strings.HasSuffix(pathMajor, "-unstable") {
		pathMajor = strings.TrimSuffix(pathMajor, "-unstable")
	}
	if strings.HasPrefix(v, "v0.0.0-") && pathMajor == ".v1" {
		return nil
	}
	m := semverMajor(v)
	if pathMajor == "" {
		if m == "v0" || m == "v1" || strings.HasSuffix(v, "+incompatible") {
			return nil
		}
		pathMajor = "v0 or v1"
	} else if pathMajor[0] == '/' || pathMajor[0] == '.' {
		if m == pathMajor[1:] {
			return nil
		}
		pathMajor = pathMajor[1:]
	}
	return fmt.Errorf("version %q invalid: should be %s, not %s", v, pathMajor, m)
}

// --- minimal semver handling ---

func semverMajor(v string) string {
	if !strings.HasPrefix(v, "v") {
		return ""
	}
	i := 1
	for i < len(v) && v[i] >= '0' && v[i] <= '9' {
		i++
	}
	return v[:i]
}

func canonicalSemver(v string) string {
	p, ok := parseSemver(v)
	if !ok {
		return ""
	}
	if p.build != "" {
		return v[:len(v)-len(p.build)]
	}
	if p.short != "" {
		return v + p.short
	}
	return v
}

type semverParsed struct {
	major, minor, patch, short, prerelease, build string
}

func parseSemver(v string) (p semverParsed, ok bool) {
	if v == "" || v[0] != 'v' {
		return
	}
	var num func(string) (string, string, bool)
	num = func(s string) (string, string, bool) {
		i := 0
		for i < len(s) && '0' <= s[i] && s[i] <= '9' {
			i++
		}
		if i == 0 || (s[0] == '0' && i != 1) {
			return "", "", false
		}
		return s[:i], s[i:], true
	}
	if p.major, v, ok = num(v[1:]); !ok {
		return
	}
	if v == "" {
		p.minor = "0"
		p.patch = "0"
		p.short = ".0.0"
		return p, true
	}
	if v[0] != '.' {
		ok = false
		return
	}
	if p.minor, v, ok = num(v[1:]); !ok {
		return
	}
	if v == "" {
		p.patch = "0"
		p.short = ".0"
		return p, true
	}
	if v[0] != '.' {
		ok = false
		return
	}
	if p.patch, v, ok = num(v[1:]); !ok {
		return
	}
	if len(v) > 0 && v[0] == '-' {
		i := 1
		for i < len(v) && v[i] != '+' {
			i++
		}
		p.prerelease = v[:i]
		if !semverIdentList(p.prerelease[1:], true) {
			ok = false
			return
		}
		v = v[i:]
	}
	if len(v) > 0 && v[0] == '+' {
		p.build = v
		if !semverIdentList(v[1:], false) {
			ok = false
			return
		}
		v = ""
	}
	if v != "" {
		ok = false
		return
	}
	ok = true
	return
}

func semverIdentList(s string, numericCheck bool) bool {
	if s == "" {
		return false
	}
	for _, part := range strings.Split(s, ".") {
		if part == "" {
			return false
		}
		allDigits := true
		for _, c := range part {
			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '-') {
				return false
			}
			if c < '0' || c > '9' {
				allDigits = false
			}
		}
		if numericCheck && allDigits && len(part) > 1 && part[0] == '0' {
			return false
		}
	}
	return true
}
