type listError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type listPackage struct {
	Name         string
	ImportPath   string
	Error        *listError
	DepOnly      bool
	Imports      []string
	ImportMap    map[string]string
	TestImports  []string
	XTestImports []string
