cat > /workspace/packages.go <<'EOF'
package main

// Loading of package information through the "go list" command, mirroring
// the behaviour of the go/packages "go list" driver for the subset of
// functionality used here (package names of imports and error reporting).

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"reflect"
	"sort"
	"strings"
	"unicode"
)

type listError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type listPackage struct {
	Name         string
	ImportPath   string
	Error        *listError
	DepOnly      bool
	Imports      []string
	ImportMap    map[string]string
	TestImports  []string
	XTestImports []string
}

type pkgError struct {
	Pos string
	Msg string
}

func (e pkgError) Error() string {
	pos := e.Pos
	if pos == "" {
		pos = "-"
	}
	return pos + ": " + e.Msg
}

type loadedPackage struct {
	ID      string
	Name    string
	Errors  []pkgError
	imports map[string]string // import path -> package ID
	Imports map[string]*loadedPackage
}

type goRunner struct {
	dir       string
	buildFlag []string
}

func (r *goRunner) env(extra ...string) []string {
	env := os.Environ()
	env = append(env, os.Environ()...)
	env = append(env, extra...)
	if r.dir != "" {
		env = append(env, "PWD="+r.dir)
	}
	return env
}

// run executes the go command and returns stdout/stderr and the raw error.
func (r *goRunner) runRaw(verb string, buildFlags []string, args []string, extraEnv ...string) (*bytes.Buffer, *bytes.Buffer, error, error) {
	goArgs := []string{verb}
	goArgs = append(goArgs, buildFlags...)
	goArgs = append(goArgs, args...)

	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}
	cmd := exec.CommandContext(context.Background(), "go", goArgs...)
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	cmd.Env = r.env(extraEnv...)
	if r.dir != "" {
		cmd.Dir = r.dir
	}
	rawErr := cmd.Run()
	var friendly error
	if rawErr != nil {
		friendly = rawErr
		var ee *exec.Error
		if errors.As(rawErr, &ee) && ee.Err == exec.ErrNotFound {
			friendly = fmt.Errorf("go command required, not found: %v", ee)
		}
		friendly = fmt.Errorf("err: %v: stderr: %s", friendly, stderr)
	}
	return stdout, stderr, friendly, rawErr
}

func (r *goRunner) goVersion() (int, error) {
	stdout, _, friendly, rawErr := r.runRaw("list", nil, []string{"-e", "-f", "{{context.ReleaseTags}}", "--", "unsafe"}, "GO111MODULE=off")
	if rawErr != nil {
		return 0, friendly
	}
	out := stdout.String()
	if len(out) < 3 {
		return 0, fmt.Errorf("bad ReleaseTags output: %q", out)
	}
	tags := strings.Fields(out[1 : len(out)-2])
	for i := len(tags) - 1; i >= 0; i-- {
		var version int
		if _, err := fmt.Sscanf(tags[i], "go1.%d", &version); err != nil {
			continue
		}
		return version, nil
	}
	return 0, fmt.Errorf("no parseable ReleaseTags in %v", tags)
}

func isPkgPathRune(r rune) bool {
	return unicode.IsOneOf([]*unicode.RangeTable{unicode.L, unicode.M, unicode.N, unicode.P, unicode.S}, r) &&
		!strings.ContainsRune("!\"#$%&'()*,:;<=>?[\\]^`{|}\uFFFD", r)
}

// invokeList runs "go list" and applies the same error handling as the
// go/packages driver.
func (r *goRunner) invokeList(args []string) (*bytes.Buffer, error) {
	stdout, stderr, friendly, err := r.runRaw("list", r.buildFlag, args)
	if err == nil {
		return stdout, nil
	}
	var ee *exec.Error
	if errors.As(err, &ee) && ee.Err == exec.ErrNotFound {
		return nil, fmt.Errorf("'go list' driver requires 'go', but %s", exec.ErrNotFound)
	}
	exitErr, ok := err.(*exec.ExitError)
	if !ok {
		return nil, fmt.Errorf("couldn't run 'go': %w", err)
	}
	se := stderr.String()
	if strings.Contains(se, "flag provided but not defined") {
		return nil, fmt.Errorf("unsupported version of go: %s: %s", exitErr, stderr)
	}
	if len(se) > 0 && strings.Contains(se, "unexpected directory layout") {
		return nil, friendly
	}
	if len(se) > 0 && strings.Contains(se, "go: no such tool") {
		return nil, friendly
	}
	msg := se
	for strings.HasPrefix(msg, "go: downloading") {
		msg = msg[strings.IndexRune(msg, '\n')+1:]
	}
	if len(se) > 0 && strings.HasPrefix(se, "# ") {
		msg := msg[len("# "):]
		if strings.HasPrefix(strings.TrimLeftFunc(msg, isPkgPathRune), "\n") {
			return stdout, nil
		}
		if strings.HasPrefix(msg, "pkg-config") {
			return stdout, nil
		}
	}
	if len(se) > 0 && strings.Contains(se, "named files must be .go files") {
		output := fmt.Sprintf(`{"ImportPath": "command-line-arguments","Incomplete": true,"Error": {"Err": %q}}`, strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	if len(se) > 0 && strings.Contains(se, "named files must all be in one directory") {
		output := fmt.Sprintf(`{"ImportPath": "command-line-arguments","Incomplete": true,"Error": {"Err": %q}}`, strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	const noSuchDirectory = "no such directory"
	if len(se) > 0 && strings.Contains(se, noSuchDirectory) {
		abspath := strings.TrimSpace(se[strings.Index(se, noSuchDirectory)+len(noSuchDirectory):])
		output := fmt.Sprintf(`{"ImportPath": %q,"Incomplete": true,"Error": {"Err": %q}}`, abspath, strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	if len(se) > 0 && strings.Contains(se, "no such file or directory") {
		output := fmt.Sprintf(`{"ImportPath": "command-line-arguments","Incomplete": true,"Error": {"Err": %q}}`, strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	if len(se) > 0 && strings.Contains(se, "outside available modules") {
		output := fmt.Sprintf(`{"ImportPath": %q,"Incomplete": true,"Error": {"Err": %q}}`, "command-line-arguments", strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	if len(se) > 0 && strings.Contains(se, "outside module root") {
		output := fmt.Sprintf(`{"ImportPath": %q,"Incomplete": true,"Error": {"Err": %q}}`, "command-line-arguments", strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	if len(se) > 0 && strings.Contains(se, "no Go files in") {
		if len(stdout.String()) > 0 {
			return stdout, nil
		}
		var importPath string
		colon := strings.Index(se, ":")
		if colon > 0 && strings.HasPrefix(se, "go build ") {
			importPath = se[len("go build "):colon]
		}
		output := fmt.Sprintf(`{"ImportPath": %q,"Incomplete": true,"Error": {"Err": %q}}`, importPath, strings.Trim(se, "\n"))
		return bytes.NewBufferString(output), nil
	}
	return nil, friendly
}

func jsonFlag(goVersion int) string {
	if goVersion < 19 {
		return "-json"
	}
	return "-json=Name,ImportPath,Error,DepOnly,Imports,ImportMap,TestImports,XTestImports"
}

// loadPackages loads the package located in dir (and its dependencies,
// including test variants) and returns the root packages.
func loadPackages(dir string, buildFlags []string) ([]*loadedPackage, error) {
	r := &goRunner{dir: dir, buildFlag: buildFlags}
	goVersion, err := r.goVersion()
	if err != nil {
		return nil, err
	}
	args := []string{"-e", jsonFlag(goVersion), "-compiled=false", "-test=true", "-export=false", "-deps=true", "-find=false"}
	if goVersion >= 21 {
		args = append(args, "-pgo=off")
	}
	args = append(args, buildFlags...)
	args = append(args, "--")

	buf, err := r.invokeList(args)
	if err != nil {
		return nil, err
	}

	seen := make(map[string]*listPackage)
	additionalErrors := make(map[string][]pkgError)
	var pkgs []*loadedPackage
	byID := make(map[string]*loadedPackage)
	var roots []string

	for dec := json.NewDecoder(buf); dec.More(); {
		p := new(listPackage)
		if err := dec.Decode(p); err != nil {
			return nil, fmt.Errorf("JSON decoding failed: %v", err)
		}
		if p.ImportPath == "" {
			if p.Error != nil {
				return nil, pkgError{Pos: p.Error.Pos, Msg: p.Error.Err}
			}
			return nil, fmt.Errorf("package missing import path: %+v", p)
		}

		if old, found := seen[p.ImportPath]; found {
			if old.Error == nil && p.Error == nil {
				if !reflect.DeepEqual(p, old) {
					return nil, fmt.Errorf("internal error: go list gives conflicting information for package %v", p.ImportPath)
				}
				continue
			}
			if old.Error != nil {
				var errkind string
				if strings.Contains(old.Error.Err, "not an importable package") {
					errkind = "not an importable package"
				} else if strings.Contains(old.Error.Err, "use of internal package") && strings.Contains(old.Error.Err, "not allowed") {
					errkind = "use of internal package not allowed"
				}
				if errkind != "" {
					if len(old.Error.ImportStack) < 1 {
						return nil, fmt.Errorf(`internal error: go list gave a %q error with empty import stack`, errkind)
					}
					importingPkg := old.Error.ImportStack[len(old.Error.ImportStack)-1]
					if importingPkg == old.ImportPath {
						if len(old.Error.ImportStack) < 2 {
							return nil, fmt.Errorf(`internal error: go list gave a %q error with an import stack without importing package`, errkind)
						}
						importingPkg = old.Error.ImportStack[len(old.Error.ImportStack)-2]
					}
					additionalErrors[importingPkg] = append(additionalErrors[importingPkg], pkgError{Pos: old.Error.Pos, Msg: old.Error.Err})
				}
			}
			if old.Error == nil {
				continue
			}
		}
		seen[p.ImportPath] = p

		pkg := &loadedPackage{ID: p.ImportPath, Name: p.Name, imports: map[string]string{}}
		ids := make(map[string]bool)
		for _, id := range p.Imports {
			ids[id] = true
		}
		for path, id := range p.ImportMap {
			pkg.imports[path] = id
			delete(ids, id)
		}
		for id := range ids {
			if id == "C" {
				continue
			}
			pkg.imports[id] = id
		}
		if !p.DepOnly {
			roots = append(roots, pkg.ID)
		}
		if p.Error != nil {
			msg := strings.TrimSpace(p.Error.Err)
			if msg == "import cycle not allowed" && len(p.Error.ImportStack) != 0 {
				msg += fmt.Sprintf(": import stack: %v", p.Error.ImportStack)
			}
			pkg.Errors = append(pkg.Errors, pkgError{Pos: p.Error.Pos, Msg: msg})
		}
		pkgs = append(pkgs, pkg)
	}

	for _, pkg := range pkgs {
		pkg.Errors = append(pkg.Errors, additionalErrors[pkg.ID]...)
	}
	// Later duplicates replace earlier ones.
	for _, pkg := range pkgs {
		byID[pkg.ID] = pkg
	}
	for _, pkg := range byID {
		pkg.Imports = make(map[string]*loadedPackage, len(pkg.imports))
		for path, id := range pkg.imports {
			if imp, ok := byID[id]; ok {
				pkg.Imports[path] = imp
			}
		}
	}

	var result []*loadedPackage
	rootSeen := map[string]bool{}
	for _, id := range roots {
		if rootSeen[id] {
			continue
		}
		rootSeen[id] = true
		if p, ok := byID[id]; ok {
			result = append(result, p)
		}
	}
	return result, nil
}

// printPackageErrors prints all errors of the packages and their transitive
// dependencies (dependencies first) and returns the number of errors.
func printPackageErrors(pkgs []*loadedPackage) int {
	var n int
	seen := make(map[*loadedPackage]bool)
	var visit func(*loadedPackage)
	visit = func(pkg *loadedPackage) {
		if seen[pkg] {
			return
		}
		seen[pkg] = true
		paths := make([]string, 0, len(pkg.Imports))
		for path := range pkg.Imports {
			paths = append(paths, path)
		}
		sort.Strings(paths)
		for _, path := range paths {
			visit(pkg.Imports[path])
		}
		for _, err := range pkg.Errors {
			fmt.Fprintln(os.Stderr, err)
			n++
		}
	}
	for _, pkg := range pkgs {
		visit(pkg)
	}
	return n
}

// loadPackageDependencies returns a map of import path to package name for
// all imports of the package located in dir.
func loadPackageDependencies(dir, buildTag string) (map[string]string, error) {
	var buildFlags []string
	if buildTag != "" {
		buildFlags = []string{fmt.Sprintf("-tags=%s", buildTag)}
	}
	pkgs, err := loadPackages(dir, buildFlags)
	if err != nil {
		return nil, err
	}
	if printPackageErrors(pkgs) > 0 {
		if buildTag != "" {
			return loadPackageDependencies(dir, "")
		}
		return nil, errors.New("package has an errors")
	}
	result := map[string]string{}
	for _, pkg := range pkgs {
		for path, imp := range pkg.Imports {
			result[path] = imp.Name
		}
	}
	return result, nil
}
