{"command":"cat > /workspace/reviser.go <<'EOF'
package main

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"io"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

const standardInput = "<standard-input>"

var errEmptyGroup = errors.New("empty")

// importGroup identifies a group of imports in the output.
type importGroup int

const (
	groupStd importGroup = iota
	groupGeneral
	groupCompany
	groupProject
	groupBlanked
	groupDotted
)

var groupNames = map[string]importGroup{
	"std":     groupStd,
	"general": groupGeneral,
	"company": groupCompany,
	"project": groupProject,
	"blanked": groupBlanked,
	"dotted":  groupDotted,
}

// parseImportsOrder validates and parses the -imports-order flag value.
func parseImportsOrder(order string) ([]importGroup, error) {
	if order == "" {
		order = "std,general,company,project"
	}
	var groups []importGroup
	present := map[importGroup]bool{}
	for _, item := range strings.Split(order, ",") {
		item = strings.TrimSpace(item)
		g, ok := groupNames[item]
		if !ok {
			return nil, fmt.Errorf("unknown order group type: %q", item)
		}
		groups = append(groups, g)
		present[g] = true
	}
	if !present[groupStd] || !present[groupGeneral] || !present[groupCompany] || !present[groupProject] {
		return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "std,general,company,project"`)
	}
	return groups, nil
}

type commentsMetadata struct {
	Doc     *ast.CommentGroup
	Comment *ast.CommentGroup
}

type fixOptions struct {
	removeUnused     bool
	useAliasForVer   bool
	format           bool
	applyToGenerated bool
	companyPrefixes  []string
	importsOrder     []importGroup
	separateNamed    bool
}

type sourceFile struct {
	projectName string
	filePath    string
	opts        *fixOptions
}

func newSourceFile(projectName, filePath string, opts *fixOptions) *sourceFile {
	return &sourceFile{projectName: projectName, filePath: filePath, opts: opts}
}

// Fix processes the file and returns the formatted content and whether it
// differs from the original content.
func (f *sourceFile) Fix() ([]byte, bool, error) {
	var originalContent []byte
	var err error
	if f.filePath == standardInput {
		originalContent, err = io.ReadAll(os.Stdin)
	} else {
		originalContent, err = os.ReadFile(f.filePath)
	}
	if err != nil {
		return nil, false, err
	}

	fset := token.NewFileSet()
	pf, err := parser.ParseFile(fset, f.filePath, originalContent, parser.ParseComments)
	if err != nil {
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %w", err)
	}

	if !f.opts.applyToGenerated && isFileAutoGenerated(pf) {
		return originalContent, false, nil
	}

	importsWithMetadata, err := f.parseImports(pf)
	if err != nil {
		return nil, false, err
	}

	groups := f.groupImports(importsWithMetadata)

	decls, ok := hasMultipleImportDecls(pf)
	if ok {
		pf.Decls = decls
	}

	f.fixImports(pf, groups, importsWithMetadata)

	f.formatDecls(pf)

	fixedImportsContent, err := generateFile(fset, pf)
	if err != nil {
		return nil, false, err
	}

	formattedContent, err := format.Source(fixedImportsContent)
	if err != nil {
		return nil, false, err
	}

	return formattedContent, !bytes.Equal(originalContent, formattedContent), nil
}

func generateFile(fset *token.FileSet, f *ast.File) ([]byte, error) {
	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, f); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func isFileAutoGenerated(file *ast.File) bool {
	const prefix = "// Code generated "
	const suffix = " DO NOT EDIT."
	for _, group := range file.Comments {
		for _, comment := range group.List {
			if comment.Pos() > file.Package {
				break
			}
			if rest, ok := strings.CutPrefix(comment.Text, prefix); ok {
				if _, ok := strings.CutSuffix(rest, suffix); ok {
					return true
				}
			}
		}
	}
	return false
}

func parseBuildTag(f *ast.File) string {
	for _, group := range f.Comments {
		for _, comment := range group.List {
			if strings.HasPrefix(comment.Text, "//go:build") {
				return strings.TrimSpace(strings.TrimPrefix(comment.Text, "//go:build"))
			}
		}
	}
	return ""
}

func isSingleCgoImport(dd *ast.GenDecl) bool {
	if dd.Tok != token.IMPORT {
		return false
	}
	if len(dd.Specs) != 1 {
		return false
	}
	return dd.Specs[0].(*ast.ImportSpec).Path.Value == `"C"`
}

func importPathOf(spec *ast.ImportSpec) string {
	return strings.Trim(spec.Path.Value, `"`)
}

func (f *sourceFile) packageDir() string {
	return filepath.Dir(f.filePath)
}

func (f *sourceFile) parseImports(file *ast.File) (map[string]*commentsMetadata, error) {
	importsWithMetadata := map[string]*commentsMetadata{}

	var packageImports map[string]string
	if f.opts.removeUnused || f.opts.useAliasForVer {
		var err error
		packageImports, err = loadPackageDependencies(f.packageDir(), parseBuildTag(file))
		if err != nil {
			return nil, err
		}
	}

	for _, decl := range file.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		if isSingleCgoImport(dd) {
			continue
		}
		if dd.Tok != token.IMPORT {
			continue
		}
		for _, spec := range dd.Specs {
			importSpec := spec.(*ast.ImportSpec)

			if f.opts.removeUnused {
				if !usesImport(file, packageImports, importPathOf(importSpec)) {
					continue
				}
			}

			var importSpecStr string
			if importSpec.Name != nil {
				importSpecStr = importSpec.Name.String() + " " + importSpec.Path.Value
			} else if f.opts.useAliasForVer {
				importSpecStr = setAliasForVersionedImportSpec(importSpec, packageImports)
			} else {
				importSpecStr = importSpec.Path.Value
			}

			importsWithMetadata[importSpecStr] = &commentsMetadata{
				Doc:     importSpec.Doc,
				Comment: importSpec.Comment,
			}
		}
	}
	return importsWithMetadata, nil
}

func setAliasForVersionedImportSpec(importSpec *ast.ImportSpec, packageImports map[string]string) string {
	imprt := importPathOf(importSpec)
	aliasName := packageImports[imprt]
	if aliasName != "" && aliasName != path.Base(imprt) {
		return aliasName + " " + importSpec.Path.Value
	}
	return importSpec.Path.Value
}

func packageNameOf(packageImports map[string]string, pkgPath string) string {
	if name, ok := packageImports[pkgPath]; ok {
		return name
	}
	return path.Base(pkgPath)
}

// usesImport reports whether the import with the given path is in use.
func usesImport(f *ast.File, packageImports map[string]string, importPath string) bool {
	names := map[string]bool{}
	var lastName string
	found := false
	for _, spec := range f.Imports {
		name := spec.Name.String()
		switch name {
		case "<nil>":
			name = packageNameOf(packageImports, importPathOf(spec))
			if importPathOf(spec) == importPath {
				names[name] = true
			}
		case "_", ".":
			return true
		}
		if importPathOf(spec) == importPath {
			lastName = name
			found = true
		}
	}
	if !found {
		return false
	}
	names[lastName] = true

	used := false
	ast.Inspect(f, func(n ast.Node) bool {
		if used {
			return false
		}
		sel, ok := n.(*ast.SelectorExpr)
		if ok {
			if id, ok := sel.X.(*ast.Ident); ok && id.Obj == nil && names[id.Name] {
				used = true
				return false
			}
		}
		return true
	})
	return used
}

type importEntry struct {
	key  string
	name string
	path string
}

func splitImportKey(key string) (name, quotedPath string) {
	if i := strings.Index(key, " "); i >= 0 {
		return key[:i], key[i+1:]
	}
	return "", key
}

type groupedImports map[importGroup][]importEntry

func (f *sourceFile) hasGroup(g importGroup) bool {
	for _, x := range f.opts.importsOrder {
		if x == g {
			return true
		}
	}
	return false
}

func (f *sourceFile) isProjectImport(pkgPath string) bool {
	return pkgPath == f.projectName || strings.HasPrefix(pkgPath, f.projectName+"/")
}

func (f *sourceFile) isCompanyImport(pkgPath string) bool {
	for _, prefix := range f.opts.companyPrefixes {
		if strings.HasPrefix(pkgPath, prefix) {
			return true
		}
	}
	return false
}

func (f *sourceFile) groupImports(importsWithMetadata map[string]*commentsMetadata) groupedImports {
	result := groupedImports{}
	hasBlanked := f.hasGroup(groupBlanked)
	hasDotted := f.hasGroup(groupDotted)
	for key := range importsWithMetadata {
		name, quoted := splitImportKey(key)
		pkgPath := strings.Trim(quoted, `"`)
		e := importEntry{key: key, name: name, path: pkgPath}
		var g importGroup
		switch {
		case hasBlanked && name == "_":
			g = groupBlanked
		case hasDotted && name == ".":
			g = groupDotted
		case isStdPackage(pkgPath):
			g = groupStd
		case f.isProjectImport(pkgPath):
			g = groupProject
		case f.isCompanyImport(pkgPath):
			g = groupCompany
		default:
			g = groupGeneral
		}
		result[g] = append(result[g], e)
	}
	for g := range result {
		entries := result[g]
		sort.Slice(entries, func(i, j int) bool {
			if entries[i].path != entries[j].path {
				return entries[i].path < entries[j].path
			}
			return entries[i].name < entries[j].name
		})
	}
	return result
}

func isStdPackage(p string) bool {
	_, ok := stdPackages[p]
	return ok
}

func hasMultipleImportDecls(f *ast.File) ([]ast.Decl, bool) {
	importSpecs := make([]ast.Spec, 0, len(f.Imports))
	for _, importSpec := range f.Imports {
		importSpecs = append(importSpecs, importSpec)
	}

	var (
		hasMultiple  bool
		firstDefined bool
	)

	decls := make([]ast.Decl, 0, len(f.Decls))
	for _, decl := range f.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok {
			decls = append(decls, decl)
			continue
		}
		if dd.Tok != token.IMPORT || isSingleCgoImport(dd) {
			decls = append(decls, dd)
			continue
		}
		if firstDefined {
			hasMultiple = true
			if len(decls) > 0 {
				if stored, ok := decls[len(decls)-1].(*ast.GenDecl); ok && stored.Tok == token.IMPORT {
					stored.Rparen = dd.End()
				}
			}
			continue
		}
		dd.Specs = importSpecs
		decls = append(decls, dd)
		firstDefined = true
	}
	return decls, hasMultiple
}

type importPosition struct {
	Start token.Pos
	End   token.Pos
}

func (p *importPosition) IsInRange(comment *ast.CommentGroup) bool {
	return p.Start <= comment.Pos() && comment.Pos() <= p.End
}

func (f *sourceFile) fixImports(file *ast.File, groups groupedImports, commentsMeta map[string]*commentsMetadata) {
	var positions []*importPosition
	for _, decl := range file.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		if dd.Tok != token.IMPORT {
			continue
		}
		if isSingleCgoImport(dd) {
			continue
		}
		positions = append(positions, &importPosition{Start: dd.Pos(), End: dd.End()})
		dd.Specs = f.rebuildImports(dd.Tok, commentsMeta, groups)
	}
	clearImportDocs(file, positions)
	removeEmptyImportNode(file)
}

func clearImportDocs(f *ast.File, positions []*importPosition) {
	if len(positions) == 0 {
		return
	}
	comments := make([]*ast.CommentGroup, 0, len(f.Comments))
	for _, comment := range f.Comments {
		inRange := false
		for _, p := range positions {
			if p.IsInRange(comment) {
				inRange = true
				break
			}
		}
		if !inRange {
			comments = append(comments, comment)
		}
	}
	if len(f.Imports) > 0 {
		f.Comments = comments
	}
}

func removeEmptyImportNode(f *ast.File) {
	decls := make([]ast.Decl, 0, len(f.Decls))
	for _, decl := range f.Decls {
		dd, ok := decl.(*ast.GenDecl)
		if ok && dd.Tok == token.IMPORT && len(dd.Specs) == 0 {
			continue
		}
		decls = append(decls, decl)
	}
	f.Decls = decls
}

func importWithComment(key string, commentsMeta map[string]*commentsMetadata) string {
	var comment string
	if meta, ok := commentsMeta[key]; ok && meta != nil && meta.Comment != nil && len(meta.Comment.List) > 0 {
		parts := make([]string, 0, len(meta.Comment.List))
		for _, c := range meta.Comment.List {
			parts = append(parts, c.Text)
		}
		comment = strings.Join(parts, " ")
	}
	if comment == "" {
		return key
	}
	return key + " " + comment
}

func (f *sourceFile) rebuildImports(tok token.Token, commentsMeta map[string]*commentsMetadata, groups groupedImports) []ast.Spec {
	var specs []ast.Spec
	newSpec := func(value string) ast.Spec {
		return &ast.ImportSpec{Path: &ast.BasicLit{Value: value, Kind: tok}}
	}
	separator := func() {
		if len(specs) > 0 {
			specs = append(specs, newSpec(""))
		}
	}
	for _, g := range f.opts.importsOrder {
		entries := groups[g]
		if len(entries) == 0 {
			continue
		}
		if f.opts.separateNamed {
			var unnamed, named []importEntry
			for _, e := range entries {
				if e.name != "" {
					named = append(named, e)
				} else {
					unnamed = append(unnamed, e)
				}
			}
			if len(unnamed) > 0 {
				separator()
				for _, e := range unnamed {
					specs = append(specs, newSpec(importWithComment(e.key, commentsMeta)))
				}
			}
			if len(named) > 0 {
				separator()
				for _, e := range named {
					specs = append(specs, newSpec(importWithComment(e.key, commentsMeta)))
				}
			}
			continue
		}
		separator()
		for _, e := range entries {
			specs = append(specs, newSpec(importWithComment(e.key, commentsMeta)))
		}
	}
	return specs
}

func (f *sourceFile) formatDecls(file *ast.File) {
	if !f.opts.format {
		return
	}
	for _, decl := range file.Decls {
		switch dd := decl.(type) {
		case *ast.GenDecl:
			dd.Doc = fixCommentGroup(dd.Doc)
		case *ast.FuncDecl:
			dd.Doc = fixCommentGroup(dd.Doc)
		}
	}
}

func fixCommentGroup(cg *ast.CommentGroup) *ast.CommentGroup {
	if cg == nil {
		return &ast.CommentGroup{List: []*ast.Comment{}}
	}
	formatted := &ast.CommentGroup{List: make([]*ast.Comment, len(cg.List))}
	copy(formatted.List, cg.List)
	return formatted
}
