package main

import (
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"strings"
)

type sourceDir struct {
	projectName     string
	dir             string
	isRecursive     bool
	excludePatterns []string
	opts            *fixOptions
}

func newSourceDir(projectName, dirPath string, isRecursive bool, excludes string, opts *fixOptions) *sourceDir {
	absPath, err := filepath.Abs(dirPath)
	if err != nil {
		absPath = dirPath
	}
	var patterns []string
	if excludes != "" {
		for _, exclude := range strings.Split(excludes, ",") {
			exclude = strings.TrimSpace(exclude)
			if exclude == "" {
				continue
			}
			if !filepath.IsAbs(exclude) {
				exclude = filepath.Join(absPath, exclude)
			}
			patterns = append(patterns, exclude)
		}
	}
	return &sourceDir{
