			}
		}

		if workPath != standardInput {
			if info, err := os.Stat(workPath); err == nil && info.IsDir() {
				dir := newSourceDir(originProjectName, workPath, recursive, *excludes, opts)
				if *listFileName {
					files, err := dir.Find()
					if err != nil {
						log.Fatalf("Failed to find unformatted files %s: %+v\n", originPath, err)
					}
					for _, f := range files {
						fmt.Println(f)
					}
					continue
				}
				if err := dir.Fix(); err != nil {
					log.Fatalf("Failed to fix directory %s: %+v\n", originPath, err)
				}
				continue
			}
		}

		var cacheFile string
		if *isUseCache {
			u, err := user.Current()
			if err != nil {
				log.Fatalf("Failed to get current user: %+v\n", err)
			}
			cacheDir := filepath.Join(u.HomeDir, ".cache", "goimports-reviser")
			if err := os.MkdirAll(cacheDir, os.ModePerm); err != nil {
				log.Fatalf("Failed to create cache directory: %+v\n", err)
			}
			cacheFile = filepath.Join(cacheDir, md5Hex([]byte(workPath)))
			if cacheContent, err := os.ReadFile(cacheFile); err == nil {
				if fileContent, err := os.ReadFile(workPath); err == nil {
					if string(cacheContent) == md5Hex(fileContent) {
						continue
					}
				}
			}
		}

		formattedOutput, hasChange, err := newSourceFile(originProjectName, workPath, opts).Fix()
		if err != nil {
			log.Fatalf("Failed to fix file: %+v\n", err)
		}

		if *isUseCache {
			if err := os.WriteFile(cacheFile, []byte(md5Hex(formattedOutput)), 0o644); err != nil {
				log.Fatalf("Failed to write cache file: %+v\n", err)
			}
		}

		resultPostProcess(hasChange, workPath, formattedOutput)
	}

	if len(deprecatedMessages) > 0 {
		for _, msg := range deprecatedMessages {
			log.Println(msg)
		}
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
		os.Exit(1)
	}

	os.Exit(exitCode)
}

// determineProjectName returns the project name either from the flag or
// from the closest go.mod file.
func determineProjectName(projectName, filePath string) (string, error) {
	if projectName != "" {
		return projectName, nil
	}
	root := projectRootPath(filePath)
	return moduleName(root)
}

func projectRootPath(filePath string) string {
	dir := filePath
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

func moduleName(root string) (string, error) {
	goModFile := filepath.Join(root, "go.mod")
	data, err := os.ReadFile(goModFile)
	if err != nil {
		return "", err
	}
	modPath, hasModule, err := parseGoMod(goModFile, data)
	if err != nil {
		return "", err
	}
	if !hasModule {
		return "", fmt.Errorf("module is undefined")
	}
	return modPath, nil
}
