func main() {
	src, _ := os.ReadFile(os.Args[1])
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "a.go", src, parser.ParseComments)
	var dd *ast.GenDecl
	for _, d := range f.Decls {
		if g, ok := d.(*ast.GenDecl); ok && g.Tok == token.IMPORT {
			dd = g
			break
		}
	}
