	var specs []ast.Spec
	vals := strings.Split(os.Getenv("VALS"), "|")
	vi := 0
	for _, p := range strings.Split(os.Args[2], ",") {
		v := ""
		if p == "F" {
			v = vals[vi]
			vi++
		}
		specs = append(specs, &ast.ImportSpec{Path: &ast.BasicLit{Value: v, Kind: token.IMPORT}})
	}
	dd.Specs = specs
	var cs []*ast.CommentGroup
	for _, c := range f.Comments {
		if start <= c.Pos() && c.Pos() <= end {
			continue
		}
		cs = append(cs, c)
	}
	f.Comments = cs
	var buf bytes.Buffer
	myprinter.Fprint(&buf, fset, f)
	fmt.Print(buf.String())
	fmt.Println("-----")
	out, _ := format.Source(buf.Bytes())
	fmt.Print(string(out))
}
